namespace ghidra.app.decompiler.component.hover;



using docking.widgets.fieldpanel.field;
using docking.widgets.fieldpanel.support;
using ghidra;
using ghidra.app.plugin.core.hover;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.util;

public class ReferenceDecompilerHover : AbstractReferenceHover, DecompilerHoverService {

	private static readonly string NAME = "Decompiler Reference Viewer";
	private static readonly string DESCRIPTION =
		"Shows \"referred to\" code and data from the decompiler.";

	// note: this is relative to other DecompilerHovers; a higher priority gets called first
	// Use high value so this hover gets called first.  The method for determining what the user
	// is hovering in the Decompiler is less then perfect.  We choose to allow the more precise
	// hovers get a chance to process the request first.
	private static readonly int PRIORITY = 50;

	public ReferenceDecompilerHover(PluginTool tool) : base(tool, PRIORITY)
    {
	}

	/* @Override */
	protected string getName() {
		return NAME;
	}

	/* @Override */
	protected string getDescription() {
		return DESCRIPTION;
	}

	/* @Override */
	protected string getOptionsCategory() {
		return GhidraOptions.CATEGORY_DECOMPILER_POPUPS;
	}

	/* @Override */
	public JComponent getHoverComponent(Program program, ProgramLocation location,
			FieldLocation fieldLocation, Field field) {

		if (!enabled || location == null) {
			return null;
		}

		Address refAddr = location.getRefAddress();
		if (refAddr == null) {
			return null;
		}
		Function other = program.getListing().getFunctionAt(refAddr);
		if (other != null) {
			return null;
		}
		return base.getHoverComponent(program, location, fieldLocation, field);

	}

}
